class Solution:
    def widestColorGap(self, colors: List[int]) -> int:
        best = 0
        n = len(colors)
        for i in range(n):
            for j in range(i + 1, n):
                if colors[i] != colors[j]:
                    best = max(best, j - i)
        return best

