function widestColorGap(colors: number[]): number {
  const n = colors.length;
  let j = n - 1;
  while (colors[j] === colors[0]) j--;
  let i = 0;
  while (colors[i] === colors[n - 1]) i++;
  return Math.max(j, n - 1 - i);
}

