    def widestColorGap(self, colors: List[int]) -> int:
        n = len(colors)
        j = n - 1
        while colors[j] == colors[0]:
            j -= 1
        i = 0
        while colors[i] == colors[n - 1]:
            i += 1
        return max(j, n - 1 - i)

